"use strict";
(async()=>{const D=await window.loadResearchData('fibonacci-data.json.gz'),$=s=>document.querySelector(s),H=[5,10,20,30,60,120];let mode='retracement',group='selected',focus=20,split='validation',page=0,visible=[],cleanup=null,opener=null;const size=15;
const pct=v=>v==null?'—':(v>0?'+':'')+(v*100).toFixed(2)+'%',rate=v=>v==null?'—':(v*100).toFixed(2)+'%',num=v=>v==null?'—':Number(v).toFixed(2),day=v=>v?String(v).replace(/(\d{4})(\d{2})(\d{2})/,'$1-$2-$3'):'—',esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),gain=v=>`<span class="${v>0?'gain':v<0?'loss':''}">${pct(v)}</span>`,weights=w=>w.map(v=>(v*100).toFixed(v===1/3?1:0)+'%').join(' / ');
const section=h=>D.report.horizons.find(x=>x.horizon===h),config=h=>section(h).modes[mode][group],data=()=>D.rows[D.aliases[`${mode}:${focus}:${group}`]];
function render(){document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.mode===mode)));$('#mode-note').textContent=mode==='retracement'?'第4档：H−1.382×(H−L)，低于原底部，属于继续下跌后的接仓。':'第4档：L+1.382×(H−L)，高于第一波高点，只有底仓已成交才追加。';
$('#horizon-rows').innerHTML=H.map(h=>{const cfg=config(h),x=cfg[split];return`<tr${h===focus?' class="current-variant"':''}><td>${h}日</td><td>${weights(cfg.weights)}</td><td>${x.n} / ${x.filled}</td><td>${gain(x.mean)}</td><td>${gain(x.median)}</td><td>${rate(x.filled_win)}</td><td>${num(x.payoff)}</td><td>${rate(x.avg_spent)}</td></tr>`}).join('');
const s=section(focus),cfg=config(focus),x=cfg[split],selected=s.modes[mode].selected,ci=group==='selected'?selected.intervals?.[split]:null,delta=selected.paired_stop_delta;$('#diagnostic-cards').innerHTML=[['当前四档预算',weights(cfg.weights),'0.382 / 0.5 / 0.618 / 1.382'],['实际多档成交',x.multi_fills+' 次',`${x.filled}次有成交，第4档${x.fourth_fills}次`],['平均收益的区块区间',ci?`${pct(ci.ci95[0])} 至 ${pct(ci.ci95[1])}`:'—',ci?`${ci.months}个月度区块，约95%区间`:'仅训练选定组提供区间']].map(([a,b,c])=>`<article><p>${a}</p><strong>${b}</strong><p>${c}</p></article>`).join('');
const names={direct:'缩量直接买入',confirm:'放量确认，不止损',stop:'放量确认 + 15%止损'};const controls=split==='all'?[]:Object.entries(s.controls).map(([key,value])=>[names[key],value[split]]);$('#comparison-rows').innerHTML=[...controls,['当前斐波那契分批',x]].map(([name,v])=>`<tr><td>${name}</td><td>${v.n} / ${v.filled}</td><td>${gain(v.mean)}</td><td>${rate(v.filled_win)}</td><td>${num(v.payoff)}</td><td>${gain(v.worst)}</td><td>${rate(v.avg_spent)}</td></tr>`).join('');
$('#comparison-note').textContent=split==='all'?'共同对照仅展示训练期及验证期；全样本含隔离期，不用于选优。':`训练选定分批组在验证期，相对放量确认＋止损的平均差为${pct(delta.mean)}${delta.interval?'，配对月度区间 '+pct(delta.interval.ci95[0])+' 至 '+pct(delta.interval.ci95[1]):''}。区间跨0时，不能据此认定更优。`;
$('#fourth-rows').innerHTML=['retracement','extension'].map(key=>{const v=s.modes[key].equal4[split];return`<tr><td>${key==='retracement'?'1.382向下回撤':'1.382向上扩展'}</td><td>${gain(v.mean)}</td><td>${rate(v.filled_win)}</td><td>${num(v.payoff)}</td><td>${v.fourth_fills}</td><td>${v.multi_fills}</td></tr>`}).join('');
$('#grid-rows').innerHTML=D.report.grid.filter(v=>v.mode===mode&&v.horizon===focus).sort((a,b)=>(b.train.mean??-Infinity)-(a.train.mean??-Infinity)).slice(0,12).map(v=>`<tr${v.weight_id===selected.weight_id?' class="current-variant"':''}><td>${weights(v.weights)}${v.weight_id===selected.weight_id?' ✓ 选定':''}</td><td>${gain(v.train.mean)}</td><td>${gain(v.validation.mean)}</td><td>${v.validation.filled}</td><td>${rate(v.validation.filled_win)}</td><td>${num(v.validation.payoff)}</td></tr>`).join('');filter()}
function filter(){const q=$('#trade-search').value.trim().toLowerCase(),fill=$('#fill-view').value,sort=$('#trade-sort').value;visible=data().filter(x=>x.included&&(split==='all'||x.split===split)&&(!q||(x.code+x.name).toLowerCase().includes(q))&&(fill==='all'||(fill==='filled'?x.spent>0:x.spent===0)));visible.sort((a,b)=>sort==='date'?b.signal_date-a.signal_date:(sort==='best'?-1:1)*(a.net-b.net));page=0;$('#download-trades').href='fib-'+D.aliases[`${mode}:${focus}:${group}`].replaceAll(':','-')+'.csv';table()}
function table(){const rows=visible.slice(page*size,(page+1)*size);$('#trade-rows').innerHTML=rows.length?rows.map(x=>`<tr><td><button class="research-stock" data-event="${x.event_id}"><strong>${esc(x.name)}</strong><small>${esc(x.code)} · ${day(x.signal_date)}</small></button></td><td>${day(x.entry_date)}</td><td>${rate(x.spent)}</td><td>${gain(x.net)}</td><td>${day(x.exit_date)}</td><td>${x.stopped?'止损退出':x.status}</td></tr>`).join(''):'<tr><td colspan="6">没有符合条件的计划</td></tr>';$('#trade-count').textContent=`共 ${visible.length} 条 · 第 ${page+1} / ${Math.max(1,Math.ceil(visible.length/size))} 页`;$('#prev-page').disabled=page===0;$('#next-page').disabled=(page+1)*size>=visible.length}
const dialog=$('#research-detail');function detail(x,button){opener=button;$('#detail-name').textContent=x.name;$('#detail-subtitle').textContent=`${x.code} · 缩量 ${day(x.signal_date)} · ${focus}日方案 · ${weights(x.weights)}`;$('#detail-metrics').innerHTML=[['总预算净收益',pct(x.net),x.status],['累计投入预算',rate(x.spent),'余款保留现金'],['第一波低点 / 高点',num(x.floor_price)+' / '+num(x.peak_price),'含影线，信号日复权'],['成交档数',x.buy_events.length+' 档',x.stopped?'触发15%止损':'固定持有期']].map(([a,b,c])=>`<div><span>${a}</span><b>${b}</b><small>${c}</small></div>`).join('');$('#detail-shape').textContent=`四档计划价 ${x.levels.map(num).join(' / ')}。${x.included?'计入共同样本。':'单独展示案例，未计入当前共同窗口样本。'} ${x.path===0?'开→高→低→收':'开→低→高→收'}路径；两种日内假设收益差${pct(x.path_gap)}。未实际触及的价位不计成交。`;
const actions=[...x.buy_events.map(b=>({date:b.date,name:'买入 '+b.level,price:b.raw_price,weight:b.weight})),...x.sell_events.map(s=>({date:s.date,name:s.reason.startsWith('full_')?'15%止损卖出':'到期卖出',price:s.raw_price,weight:null}))].sort((a,b)=>a.date-b.date);$('#detail-actions').innerHTML=actions.length?actions.map(a=>`<tr><td>${day(a.date)}</td><td>${a.name}</td><td>${num(a.price)}</td><td>${rate(a.weight)}</td></tr>`).join(''):'<tr><td colspan="4">挂单窗口内未成交，资金保持现金。</td></tr>';cleanup?.();dialog.showModal();const root=dialog.querySelector('.candle-panel');root.querySelector('h3').textContent=x.name+' · 分批成交与15%止损';cleanup=window.mountSignalCandles(root,x,null)}
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;render()}));$('#allocation').addEventListener('change',()=>{group=$('#allocation').value;render()});$('#focus-horizon').addEventListener('change',()=>{focus=Number($('#focus-horizon').value);render()});$('#split').addEventListener('change',()=>{split=$('#split').value;render()});for(const id of ['fill-view','trade-sort'])$('#'+id).addEventListener('change',filter);$('#trade-search').addEventListener('input',filter);$('#prev-page').addEventListener('click',()=>{page--;table()});$('#next-page').addEventListener('click',()=>{page++;table()});$('#trade-rows').addEventListener('click',e=>{const b=e.target.closest('[data-event]');if(b)detail(visible.find(x=>x.event_id===Number(b.dataset.event)),b)});$('#case-open').addEventListener('click',()=>{const x=data().find(x=>x.event_id===D.case_id);if(x)detail(x,$('#case-open'))});$('#close-detail').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>{cleanup?.();cleanup=null;opener?.focus()});dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});render();})().catch(window.showResearchDataError);
